$(function(){$(".address-view").click(function(n){var t=$(n.target).hide();t.siblings(".address-form").show()});$(".order-tracking input").each(function(){var n=$(this),t=n.closest(".order-tracking");n.val()!==""&&(t.find(".order-tracking-view").show(),t.find(".order-tracking-edit").hide())});$(".order-tracking button.edit-button").click(function(n){n.preventDefault();var r=$(n.target),t=r.closest(".order-tracking"),i=t.find(".order-tracking-edit-field");t.find(".order-tracking-view").hide();t.find(".order-tracking-edit").show();i.data("previous-value",i.val())});$(".order-tracking button.cancel-button").click(function(n){n.preventDefault();var r=$(n.target),t=r.closest(".order-tracking"),i=t.find(".order-tracking-edit-field");t.find(".order-tracking-view").show();t.find(".order-tracking-edit").hide();i.val(i.data("previous-value"))});$(".new-order-event-add").click(function(n){n.preventDefault();var i=$("#order-event-log-item-template").html(),f=$(n.target),t=f.closest(".order-events"),e=t.data("add-event-url"),o=t.data("order-id"),s=t.find(".new-order-event-category:checked").val()||"Note",r=t.find(".new-order-event-description"),u=r.val(),h=$("input[name='__RequestVerificationToken']").val();u&&$.post(e,{orderId:o,category:s,description:u,__RequestVerificationToken:h},function(n){if(i=="")t.find("ul.order-event-log").prepend($("<li><\/li>").append($("<h3><\/h3>").html(n.Date+" ("+n.Category+")")).append($("<p><\/p>").html(n.Description)));else{var u=i.replace("{cssclass}",n.Category.toLowerCase().replace(" ","-")).replace("{date}",n.Date).replace("{category}",n.Category).replace("{text}",n.Description).replace("{author}","");t.find("ul.order-event-log").prepend(u)}r.val("")})})});